import pandas as pd

spark.conf.set("spark.sql.execution.arrow.maxRecordsPerBatch", "4")


def describe_batches(batches):
    for number, pdf in enumerate(batches):
        yield pd.DataFrame({"batch_no": [number], "rows": [len(pdf)], "first_reading": [pdf["reading_id"].iloc[0]]})


sensor_readings.select("reading_id").mapInPandas(describe_batches, "batch_no INT, rows INT, first_reading STRING").show()

import pandas as pd
from pyspark.sql import functions as F

readings = sensor_readings.select("reading_id", "device_id", "arrival_time")


def drop_repeats(batches):
    for pdf in batches:
        yield pdf.drop_duplicates("reading_id")


for size in ["10000", "4"]:
    spark.conf.set("spark.sql.execution.arrow.maxRecordsPerBatch", size)
    kept = readings.mapInPandas(drop_repeats, readings.schema)
    print("batches of", size, "->", kept.count(), "rows; copies of R0011:", kept.filter(F.col("reading_id") == "R0011").count())
